import{_ as t,a0 as l,w as o,s as r,ao as d,I as n,x as a,a1 as p,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"使用 snapcraft 将 snap 包发布到商店 | LCTT x X-CMD","titleTemplate":false,"description":"使用 snapcraft 将 snap 包发布到商店 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 snapcraft 将 snap 包发布到商店 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 snapcraft 将 snap 包发布到商店 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20161115 Making your snaps available to the store using snapcraft","title":"使用 snapcraft 将 snap 包发布到商店","tag":"201708","desc":""},"relativePath":"201708/20161115 Making your snaps available to the store using snapcraft.md","filePath":"[post].md"}'),c={name:"201708/20161115 Making your snaps available to the store using snapcraft.md"};function h(g,s,b,u,f,k){const e=l("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="使用-snapcraft-将-snap-包发布到商店" tabindex="-1">使用 snapcraft 将 snap 包发布到商店 <a class="header-anchor" href="#使用-snapcraft-将-snap-包发布到商店" aria-label="Permalink to “使用 snapcraft 将 snap 包发布到商店”">​</a></h1><p><img src="https://insights.ubuntu.com/wp-content/uploads/9be3/Snaps.jpg" alt="snaps"></p><p>Ubuntu Core 已经正式发布（LCTT 译注：指 2016 年 11 月发布的 Ubuntu Snappy Core 16 ），也许是时候让你的 snap 包进入商店了！</p><h3 id="交付和商店的概念" tabindex="-1">交付和商店的概念 <a class="header-anchor" href="#交付和商店的概念" aria-label="Permalink to “交付和商店的概念”">​</a></h3><p>首先回顾一下我们是怎么通过商店管理 snap 包的吧。</p><p>每次你上传 snap 包，商店都会为其分配一个修订版本号，并且商店中针对特定 snap 包 的版本号都是唯一的。</p><p>但是第一次上传 snap 包的时候，我们首先要为其注册一个还没有被使用的名字，这很容易。</p><p>商店中所有的修订版本都可以释放到多个通道中，这些通道只是概念上定义的，以便给用户一个稳定或风险等级的参照，这些通道有:</p><ul><li>稳定（stable）</li><li>候选（candidate）</li><li>测试（beta）</li><li>边缘（edge）</li></ul><p>理想情况下，如果我们设置了 CI/CD 过程，那么每天或在每次更新源码时都会将其推送到边缘通道。在此过程中有两件事需要考虑。</p><p>首先在开始的时候，你最好制作一个不受限制的 snap 包，因为在这种新范例下，snap 包的大部分功能都能不受限制地工作。考虑到这一点，你的项目开始时 <code>confinement</code> 将被设置为 <code>devmode</code>（LCTT 译注：这是 <code>snapcraft.yaml</code> 中的一个键及其可选值）。这使得你在开发的早期阶段，仍然可以让你的 snap 包进入商店。一旦所有的东西都得到了 snap 包运行的安全模型的充分支持，那么就可以将 <code>confinement</code> 修改为 <code>strict</code>。</p><p>好了，假设你在限制方面已经做好了，并且也开始了一个对应边缘通道的 CI/CD 过程，但是如果你也想确保在某些情况下，早期版本 master 分支新的迭代永远也不会进入稳定或候选通道，那么我们可以使用 <code>gadge</code> 设置。如果 snap 包的 <code>gadge</code> 设置为 <code>devel</code> （LCTT注：这是 <code>snapcraft.yaml</code> 中的一个键及其可选值），商店将会永远禁止你将 snap 包释放到稳定和候选通道。</p><p>在这个过程中，我们有时可能想要发布一个修订版本到测试通道，以便让有些用户更愿意去跟踪它（一个好的发布管理流程应该比一个随机的日常构建更有用）。这个阶段结束后，如果希望人们仍然能保持更新，我们可以选择关闭测试通道，从一个特定的时间点开始我们只计划发布到候选和稳定通道，通过关闭测试通道我们将使该通道跟随稳定列表中的下一个开放通道，在这里是候选通道。而如果候选通道跟随的是稳定通道后，那么最终得到是稳定通道了。</p><h3 id="进入-snapcraft" tabindex="-1">进入 Snapcraft <a class="header-anchor" href="#进入-snapcraft" aria-label="Permalink to “进入 Snapcraft”">​</a></h3><p>那么所有这些给定的概念是如何在 snapcraft 中配合使用的？首先我们需要登录:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft login</span></span>
<span class="line"><span>Enter your Ubuntu One SSO credentials.</span></span>
<span class="line"><span>Email: sxxxxx.sxxxxxx@canonical.com</span></span>
<span class="line"><span>Password: **************</span></span>
<span class="line"><span>Second-factor auth: 123456</span></span></code></pre></div><p>在登录之后，我们就可以开始注册 snap 了。例如，我们想要注册一个虚构的 snap 包 awesome-database：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft register awesome-database</span></span>
<span class="line"><span>We always want to ensure that users get the software they expect</span></span>
<span class="line"><span>for a particular name.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If needed, we will rename snaps to ensure that a particular name</span></span>
<span class="line"><span>reflects the software most widely expected by our community.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For example, most people would expect ‘thunderbird’ to be published by</span></span>
<span class="line"><span>Mozilla. They would also expect to be able to get other snaps of</span></span>
<span class="line"><span>Thunderbird as &#39;thunderbird-sergiusens&#39;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Would you say that MOST users will expect &#39;a&#39; to come from</span></span>
<span class="line"><span>you, and be the software you intend to publish there? [y/N]: y</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are now the publisher for &#39;awesome-database&#39;</span></span></code></pre></div><p>假设我们已经构建了 snap 包，接下来我们要做的就是把它上传到商店。我们可以在同一个命令中使用快捷方式和 <code>--release</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft push awesome-databse_0.1_amd64.snap --release edge</span></span>
<span class="line"><span>Uploading awesome-database_0.1_amd64.snap [=================] 100%</span></span>
<span class="line"><span>Processing....</span></span>
<span class="line"><span>Revision 1 of &#39;awesome-database&#39; created.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Channel    Version    Revision</span></span>
<span class="line"><span>stable     -          -</span></span>
<span class="line"><span>candidate  -          -</span></span>
<span class="line"><span>beta       -          -</span></span>
<span class="line"><span>edge       0.1        1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The edge channel is now open.</span></span></code></pre></div><p>如果我们试图将其发布到稳定通道，商店将会阻止我们：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft release awesome-database 1 stable</span></span>
<span class="line"><span>Revision 1 (devmode) cannot target a stable channel (stable, grade: devel)</span></span></code></pre></div><p>这样我们不会搞砸，也不会让我们的忠实用户使用它。现在，我们将最终推出一个值得发布到稳定通道的修订版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft push awesome-databse_0.1_amd64.snap</span></span>
<span class="line"><span>Uploading awesome-database_0.1_amd64.snap [=================] 100%</span></span>
<span class="line"><span>Processing....</span></span>
<span class="line"><span>Revision 10 of &#39;awesome-database&#39; created.</span></span></code></pre></div><p>注意，<ruby>版本号<rt>version</rt></ruby>（LCTT 译注：这里指的是 snap 包名中 <code>0.1</code> 这个版本号）只是一个友好的标识符，真正重要的是商店为我们生成的<ruby>修订版本号<rt>Revision</rt></ruby>（LCTT 译注：这里生成的修订版本号为 <code>10</code>）。现在让我们把它释放到稳定通道：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snapcraft release awesome-database 10 stable</span></span>
<span class="line"><span>Channel    Version    Revision</span></span>
<span class="line"><span>stable     0.1        10</span></span>
<span class="line"><span>candidate  ^          ^</span></span>
<span class="line"><span>beta       ^          ^</span></span>
<span class="line"><span>edge       0.1        10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The &#39;stable&#39; channel is now open.</span></span></code></pre></div><p>在这个针对我们正在使用架构最终的通道映射视图中，可以看到边缘通道将会被固定在修订版本 10 上，并且测试和候选通道将会跟随现在修订版本为 10 的稳定通道。由于某些原因，我们决定将专注于稳定性并让我们的 CI/CD 推送到测试通道。这意味着我们的边缘通道将会略微过时，为了避免这种情况，我们可以关闭这个通道：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ snapcraft close awesome-database edge</span></span>
<span class="line"><span>Arch    Channel    Version    Revision</span></span>
<span class="line"><span>amd64   stable     0.1        10</span></span>
<span class="line"><span>        candidate  ^          ^</span></span>
<span class="line"><span>        beta       ^          ^</span></span>
<span class="line"><span>        edge       ^          ^</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The edge channel is now closed.</span></span></code></pre></div><p>在当前状态下，所有通道都跟随着稳定通道，因此订阅了候选、测试和边缘通道的人也将跟踪稳定通道的改动。比如就算修订版本 11 只发布到稳定通道，其他通道的人们也能看到它。</p><p>这个清单还提供了完整的体系结构视图，在本例中，我们只使用了 amd64。</p><h3 id="获得更多的信息" tabindex="-1">获得更多的信息 <a class="header-anchor" href="#获得更多的信息" aria-label="Permalink to “获得更多的信息”">​</a></h3><p>有时过了一段时间，我们想知道商店中的某个 snap 包的历史记录和现在的状态是什么样的，这里有两个命令，一个是直截了当输出当前的状态，它会给我们一个熟悉的结果:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ snapcraft status awesome-database</span></span>
<span class="line"><span>Arch    Channel    Version    Revision</span></span>
<span class="line"><span>amd64   stable     0.1        10</span></span>
<span class="line"><span>        candidate  ^          ^</span></span>
<span class="line"><span>        beta       ^          ^</span></span>
<span class="line"><span>        edge       ^          ^</span></span></code></pre></div><p>我们也可以通过下面的命令获得完整的历史记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ snapcraft history awesome-database</span></span>
<span class="line"><span>Rev.    Uploaded              Arch       Version    Channels</span></span>
<span class="line"><span>3       2016-09-30T12:46:21Z  amd64      0.1        stable*</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>2       2016-09-30T12:38:20Z  amd64      0.1        -</span></span>
<span class="line"><span>1       2016-09-30T12:33:55Z  amd64      0.1        -</span></span></code></pre></div><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to “结束语”">​</a></h3><p>希望这篇文章能让你对商店能做的事情有一个大概的了解，并让更多的人开始使用它！</p><hr>`,38)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),p(e,{href:"https://insights.ubuntu.com/2016/11/15/making-your-snaps-available-to-the-store-using-snapcraft/"},{default:i(()=>[...s[0]||(s[0]=[a("https://insights.ubuntu.com/2016/11/15/making-your-snaps-available-to-the-store-using-snapcraft/",-1)])]),_:1})]),s[14]||(s[14]=n("p",null,[n("em",null,"译者简介：")],-1)),s[15]||(s[15]=n("blockquote",null,[n("p",null,[a("snapcraft.io 的钉子户，对 Ubuntu Core、Snaps 和 Snapcraft 有着浓厚的兴趣，并致力于将这些还在快速发展的新技术通过翻译或原创的方式介绍到中文世界。有兴趣的小伙伴也可以关注译者个人的公众号： "),n("code",null,"Snapcraft"),a("，近期会在上面连载几篇有关 Core snap 发布策略、交付流程和验证流程的文章，欢迎围观 :）")])],-1)),n("p",null,[s[5]||(s[5]=a("作者：",-1)),p(e,{href:"https://insights.ubuntu.com/author/sergio-schvezov/"},{default:i(()=>[...s[2]||(s[2]=[a("Sergio Schvezov",-1)])]),_:1}),s[6]||(s[6]=a(" 译者：",-1)),p(e,{href:"https://github.com/Snapcrafter"},{default:i(()=>[...s[3]||(s[3]=[a("Snapcrafter",-1)])]),_:1}),s[7]||(s[7]=a(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[a("Linux中国",-1)])]),_:1}),s[12]||(s[12]=a(" 荣誉推出",-1))])])}const v=t(c,[["render",h]]);export{C as __pageData,v as default};
